import type { Option } from "effect";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  inputOtpGroupClassName,
  inputOtpRootClassName,
  inputOtpSeparatorClassName,
  inputOtpSlotClassName,
} from "./view";

export {
  inputOtpGroupClassName,
  inputOtpRootClassName,
  inputOtpSeparatorClassName,
  inputOtpSlotClassName,
} from "./view";

/** Shared style object for Input OTP anatomy helpers. */
export type InputOtpStyle = Readonly<Record<string, string>>;

/** Common disabled and invalid state forwarded to wrapper and slot attributes. */
export type InputOtpState = Readonly<{
  disabled?: boolean | undefined;
  invalid?: boolean | undefined;
}>;

/** Configures the root and group wrappers around OTP slots. */
export type ViewConfig = InputOtpState &
  Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  dir?: "ltr" | "rtl" | undefined;
  style?: InputOtpStyle | undefined;
}>;

/** Configures one controlled OTP slot input. */
export type SlotViewConfig<ParentMessage> = InputOtpState &
  Readonly<{
  id?: string | undefined;
  name?: string | undefined;
  value: string;
  ariaLabel: string;
  onInput: (value: string) => ParentMessage;
  onKeyDown?: ((key: string) => Option.Option<ParentMessage>) | undefined;
  inputMode?: string | undefined;
  pattern?: string | undefined;
  active?: boolean | undefined;
  className?: string | undefined;
  style?: InputOtpStyle | undefined;
}>;

/** Digits-only pattern matching shadcn/input-otp examples. */
export const REGEXP_ONLY_DIGITS = "[0-9]*";

/** Alphanumeric pattern matching shadcn/input-otp examples. */
export const REGEXP_ONLY_DIGITS_AND_CHARS = "[a-zA-Z0-9]*";

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  state: InputOtpState
) => [
  ...(state.disabled === true ? [h.DataAttribute("disabled", "")] : []),
  ...(state.invalid === true ? [h.DataAttribute("invalid", "")] : []),
];

const matchesPattern = (value: string, pattern: string): boolean =>
  new RegExp(`^(?:${pattern})$`, "u").test(value);

const patternCharacters = (value: string, pattern?: string): string =>
  pattern === undefined
    ? value
    : value
        .split("")
        .filter((character) => matchesPattern(character, pattern))
        .join("");

/** Renders the Input OTP root wrapper. */
export const rootView = <ParentMessage>({
  children,
  className,
  dir,
  style,
  ...state
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, state),
      ...(dir === undefined ? [] : [h.Attribute("dir", dir)]),
      h.DataAttribute("slot", "input-otp"),
      h.Class(classNames(inputOtpRootClassName, className)),
      h.Style(style ?? {}),
    ],
    children
  );
};

/** Renders a grouped set of adjacent OTP slots. */
export const groupView = <ParentMessage>({
  children,
  className,
  dir,
  style,
  ...state
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, state),
      ...(dir === undefined ? [] : [h.Attribute("dir", dir)]),
      h.DataAttribute("slot", "input-otp-group"),
      h.Class(classNames(inputOtpGroupClassName, className)),
      h.Style(style ?? {}),
    ],
    children
  );
};

/** Renders one controlled OTP slot input. */
export const slotView = <ParentMessage>({
  id,
  name,
  value,
  ariaLabel,
  onInput,
  onKeyDown,
  inputMode,
  pattern,
  active = false,
  className,
  style,
  ...state
}: SlotViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.input([
    ...(id === undefined ? [] : [h.Id(id)]),
    ...(name === undefined ? [] : [h.Name(name)]),
    h.Type("text"),
    h.Value(value),
    h.AriaLabel(ariaLabel),
    h.Autocomplete("one-time-code"),
    h.OnInput((nextValue) => onInput(patternCharacters(nextValue, pattern))),
    ...(onKeyDown === undefined
      ? []
      : [h.OnKeyDownPreventDefault((key) => onKeyDown(key))]),
    ...(inputMode === undefined ? [] : [h.Attribute("inputmode", inputMode)]),
    ...(pattern === undefined ? [] : [h.Attribute("pattern", pattern)]),
    ...(state.disabled === true ? [h.Disabled(true)] : []),
    ...(state.invalid === true ? [h.AriaInvalid(true)] : []),
    ...stateAttributes(h, state),
    h.DataAttribute("slot", "input-otp-slot"),
    h.DataAttribute("active", active ? "true" : "false"),
    h.DataAttribute("filled", value === "" ? "false" : "true"),
    h.Class(classNames(inputOtpSlotClassName, className)),
    h.Style(style ?? {}),
  ]);
};

/** Renders an aria-hidden visual separator between OTP groups. */
export const separatorView = <ParentMessage>(): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "input-otp-separator"),
      h.Class(inputOtpSeparatorClassName),
    ],
    ["•"]
  );
};

export const inputOtpRootClassName = "flex items-center gap-2";
export const inputOtpGroupClassName = "flex items-center";
export const inputOtpSlotClassName =
  "relative flex h-10 w-10 items-center justify-center border-y border-r border-gray-300 bg-white text-center text-sm text-gray-950 shadow-sm outline-none transition-all first:rounded-l-md first:border-l last:rounded-r-md focus:z-10 focus:border-gray-950 focus:ring-2 focus:ring-gray-950 focus:ring-offset-2 data-[active=true]:z-10 data-[active=true]:border-gray-950 data-[active=true]:ring-2 data-[active=true]:ring-gray-950 data-[active=true]:ring-offset-2";
export const inputOtpSeparatorClassName =
  "mx-2 flex h-10 items-center text-gray-950";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, test } from "vitest";

import * as InputOtp from "./index";

const view = (digit: string): Html =>
  InputOtp.rootView<string>({
    children: [
      InputOtp.groupView<string>({
        children: [
          InputOtp.slotView<string>({
            value: digit,
            ariaLabel: "Digit 1",
            onInput: (value) => value,
            active: true,
          }),
        ],
      }),
      InputOtp.separatorView<string>(),
    ],
  });

const constrainedView = (digit: string): Html =>
  InputOtp.rootView<string>({
    disabled: true,
    invalid: true,
    dir: "rtl",
    children: [
      InputOtp.groupView<string>({
        children: [
          InputOtp.slotView<string>({
            value: digit,
            ariaLabel: "Digit 1",
            onInput: (value) => value,
            pattern: InputOtp.REGEXP_ONLY_DIGITS,
            inputMode: "numeric",
            disabled: true,
            invalid: true,
          }),
        ],
      }),
    ],
  });

describe("Input OTP registry view", () => {
  test("renders one-time-code slot state", () => {
    Scene.scene(
      {
        update: (_model: string, message: string): readonly [string, []] => [
          message,
          [],
        ],
        view,
      },
      Scene.with(""),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveAttr(
        "autocomplete",
        "one-time-code"
      ),
      Scene.type(Scene.role("textbox", { name: "Digit 1" }), "4"),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveValue("4")
    );
  });

  test("forwards disabled, invalid, dir, and filters pattern input", () => {
    Scene.scene(
      {
        update: (_model: string, message: string): readonly [string, []] => [
          message,
          [],
        ],
        view: constrainedView,
      },
      Scene.with(""),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toBeDisabled(),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveAttr(
        "aria-invalid",
        "true"
      ),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveAttr(
        "pattern",
        InputOtp.REGEXP_ONLY_DIGITS
      )
    );
  });

  test("filters input through the configured pattern", () => {
    Scene.scene(
      {
        update: (_model: string, message: string): readonly [string, []] => [
          message,
          [],
        ],
        view: (digit) =>
          InputOtp.slotView<string>({
            value: digit,
            ariaLabel: "Digit 1",
            onInput: (value) => value,
            pattern: InputOtp.REGEXP_ONLY_DIGITS,
          }),
      },
      Scene.with(""),
      Scene.type(Scene.role("textbox", { name: "Digit 1" }), "A1B2"),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveValue("12")
    );
  });
});
